  g += pow(sat1(dot(n, normalize(normalize(vec3(0.0, 0.62, 0.78)) + s.V))), 700.0) * 0.6;
  g += pow(sat1(dot(n, normalize(normalize(vec3(0.6, 0.05, 0.8)) + s.V))), 700.0) * 0.5;
